1	//! D-PALETTE-NNUE (corrected) — does the CERTIFIED palette256 cosine-replacement
2	//! preserve the pairwise-cosine ranking of NNUE feature-transformer columns?
3	//!
4	//! Correction of the first cut (`stockfish-rs examples/palette_nnue.rs`), which
5	//! used a hand-rolled scalar k-means codebook and re-ran the whole eval
6	//! (materialized) — wrong tool, wrong methodology. This probe reuses the real
7	//! codec, `bgz_tensor::fisher_z::FisherZTable` (Fisher-z i8, per-family 3σ gamma;
8	//! certified ρ≥0.999 on 21 Qwen3-TTS roles / 256 Jina-v5 centroids), and measures
9	//! RANKING directly off the i8 table — no vector reconstruction. Fisher-z
10	//! (`arctanh`) is monotone, so it preserves cosine rank BY CONSTRUCTION; the only
11	//! rank-affecting step is the i8 3σ quantization, which is exactly what ρ here
12	//! measures.
13	//!
14	//! Input: the 256 FT columns (1024-dim f32) exported by
15	//! `stockfish-rs --example export_ft_columns` (32 640 off-diagonal pairs, the
16	//! Jina-v5 certification setup). Path from arg1 / `$FT_COLUMNS_OUT` / default tmp.
17	//!
18	//! Gate (anchor: certified Fisher-z lane ρ≥0.999): ρ_all ≥ 0.999 AND the hard
19	//! near-orthogonal cut ρ_mid ≥ 0.99 → GREEN (FT columns ARE a palette256 tenant:
20	//! one-table-read cosine similarity preserved). The **exit code IS the gate**:
21	//! 0 only on GREEN; non-zero on fenced OR insufficient (a missing hard cut is
22	//! withheld, never an auto-pass). The input-absent path exits 0 (CI-safe).
23	//!
24	//! Run: cargo run --manifest-path crates/bgz-tensor/Cargo.toml --release \
25	//!        --example nnue_palette_cosine -- /path/to/ft_columns.bin
26	
27	use std::path::PathBuf;
28	use std::process::ExitCode;
29	
30	use bgz_tensor::fisher_z::FisherZTable;
31	
32	fn in_path() -> PathBuf {
33	    std::env::args()
34	        .nth(1)
35	        .or_else(|| std::env::var("FT_COLUMNS_OUT").ok())
36	        .map(PathBuf::from)
37	        .unwrap_or_else(|| PathBuf::from("/tmp/ft_columns.bin"))
38	}
39	
40	fn read_columns(path: &PathBuf) -> Option<Vec<Vec<f32>>> {
41	    let bytes = std::fs::read(path).ok()?;
42	    if bytes.len() < 8 {
43	        return None;
44	    }
45	    let k = u32::from_le_bytes(bytes[0..4].try_into().unwrap()) as usize;
46	    let dim = u32::from_le_bytes(bytes[4..8].try_into().unwrap()) as usize;
47	    if bytes.len() < 8 + k * dim * 4 {
48	        return None;
49	    }
50	    let mut cols = Vec::with_capacity(k);
51	    let mut off = 8;
52	    for _ in 0..k {
53	        let mut row = Vec::with_capacity(dim);
54	        for _ in 0..dim {
55	            row.push(f32::from_le_bytes(bytes[off..off + 4].try_into().unwrap()));
56	            off += 4;
57	        }
58	        cols.push(row);
59	    }
60	    Some(cols)
61	}
62	
63	fn cosine(a: &[f32], b: &[f32]) -> f32 {
64	    let (mut dot, mut na, mut nb) = (0f64, 0f64, 0f64);
65	    for i in 0..a.len().min(b.len()) {
66	        let (x, y) = (a[i] as f64, b[i] as f64);
67	        dot += x * y;
68	        na += x * x;
69	        nb += y * y;
70	    }
71	    let d = (na * nb).sqrt();
72	    if d < 1e-15 {
73	        0.0
74	    } else {
75	        (dot / d) as f32
76	    }
77	}
78	
79	fn ranks(xs: &[f64]) -> Vec<f64> {
80	    let n = xs.len();
81	    let mut idx: Vec<usize> = (0..n).collect();
82	    idx.sort_by(|&a, &b| xs[a].partial_cmp(&xs[b]).unwrap());
83	    let mut r = vec![0f64; n];
84	    let mut i = 0;
85	    while i < n {
86	        let mut j = i + 1;
87	        while j < n && (xs[idx[j]] - xs[idx[i]]).abs() < 1e-12 {
88	            j += 1;
89	        }
90	        let avg = ((i + j - 1) as f64) / 2.0 + 1.0;
91	        for &k in &idx[i..j] {
92	            r[k] = avg;
93	        }
94	        i = j;
95	    }
96	    r
97	}
98	
99	fn pearson(a: &[f64], b: &[f64]) -> f64 {
100	    let n = a.len() as f64;
101	    let ma = a.iter().sum::<f64>() / n;
102	    let mb = b.iter().sum::<f64>() / n;
103	    let (mut num, mut da, mut db) = (0.0, 0.0, 0.0);
104	    for i in 0..a.len() {
105	        let (x, y) = (a[i] - ma, b[i] - mb);
106	        num += x * y;
107	        da += x * x;
108	        db += y * y;
109	    }
110	    if da == 0.0 || db == 0.0 {
111	        0.0
112	    } else {
113	        num / (da.sqrt() * db.sqrt())
114	    }
115	}
116	
117	fn spearman(x: &[f64], y: &[f64]) -> f64 {
118	    pearson(&ranks(x), &ranks(y))
119	}
120	
121	fn main() -> ExitCode {
122	    let path = in_path();
123	    let Some(cols) = read_columns(&path) else {
124	        println!(
125	            "nnue_palette_cosine: no FT-columns file at {} (run stockfish-rs export_ft_columns first) — skipping.",
126	            path.display()
127	        );
128	        return ExitCode::SUCCESS;
129	    };
130	    let k = cols.len();
131	    println!(
132	        "nnue_palette_cosine: {} FT columns (dim {}) loaded\n",
133	        k,
134	        cols[0].len()
135	    );
136	
137	    // The REAL certified codec: fits per-family 3σ gamma from the actual pairwise
138	    // cosines and encodes the k×k table to i8 (Fisher-z). No reconstruction.
139	    let table = FisherZTable::build(&cols, k);
140	
141	    // True vs palette-restored pairwise cosine, off-diagonal pairs.
142	    let mut t_all = Vec::new();
143	    let mut pal = Vec::new();
144	    let (mut mid_t, mut mid_p) = (Vec::new(), Vec::new());
145	    let mut mae = 0f64;
146	    let mut mx = 0f64;
147	    for i in 0..k {
148	        for j in (i + 1)..k {
149	            let t = cosine(&cols[i], &cols[j]) as f64;
150	            let p = table.lookup_f32(i as u8, j as u8) as f64;
151	            mae += (t - p).abs();
152	            mx = mx.max((t - p).abs());
153	            t_all.push(t);
154	            pal.push(p);
155	            // hard cut: near-orthogonal band |cos| ≤ 0.3, where Fisher-z stretch
156	            // is smallest and discrimination is hardest.
157	            if t.abs() <= 0.3 {
158	                mid_t.push(t);
159	                mid_p.push(p);
160	            }
161	        }
162	    }
163	    let npairs = t_all.len();
164	    mae /= npairs as f64;
165	    let rho_all = spearman(&t_all, &pal);
166	    let r_all = pearson(&t_all, &pal);
167	    let rho_mid = if mid_t.len() >= 8 {
168	        spearman(&mid_t, &mid_p)
169	    } else {
170	        f64::NAN
171	    };
172	    println!("codec: FisherZTable (Fisher-z i8, per-family 3σ gamma) — the certified palette256 cosine-replacement");
173	    println!(
174	        "       gamma z_min {:.4} z_range {:.4} | table {}×{} i8 = {} KB (one-table-read)",
175	        table.gamma.z_min,
176	        table.gamma.z_range,
177	        k,
178	        k,
179	        (k * k) / 1024
180	    );
181	    println!(
182	        "pairs: {} off-diagonal | cosine MAE {:.5}, max |Δ| {:.4} | Pearson r {:.5} | Spearman ρ {:.5}",
183	        npairs, mae, mx, r_all, rho_all
184	    );
185	    println!(
186	        "hard cut (|cos| ≤ 0.3, near-orthogonal): {} pairs | Spearman ρ {:.5}   ← the fine-discrimination bar\n",
187	        mid_t.len(),
188	        rho_mid
189	    );
190	
191	    // The gate is explicit: ρ_all ≥ 0.999 AND the hard near-orthogonal cut
192	    // ρ_mid ≥ 0.99. A missing hard cut (too few near-orthogonal pairs → ρ_mid
193	    // undefined) is NOT a pass — GREEN is withheld. Exit code IS the gate: 0 only
194	    // on GREEN; non-zero on fenced or insufficient, so automation can distinguish
195	    // a certified tenant from one where the fine-discrimination bar failed or was
196	    // never measured. (The input-absent path above still exits 0 — CI-safe.)
197	    let hard_cut_ok = rho_mid.is_finite() && rho_mid >= 0.99;
198	    if rho_all >= 0.999 && hard_cut_ok {
199	        println!(
200	            "D-PALETTE-NNUE (corrected): GREEN — ρ_all {:.5} ≥ 0.999 and near-orthogonal ρ {:.5} ≥ 0.99.\n\
201	             The NNUE FT columns ARE a palette256 tenant: the certified Fisher-z cosine-replacement\n\
202	             preserves pairwise-cosine ranking (one-table-read similarity), no materialization.\n\
203	             The earlier scalar-k-means FENCE was an artifact of the wrong codec + eval-reconstruction.",
204	            rho_all, rho_mid
205	        );
206	        ExitCode::SUCCESS
207	    } else if !rho_mid.is_finite() {
208	        println!(
209	            "D-PALETTE-NNUE (corrected): INSUFFICIENT — the near-orthogonal hard cut had < 8 pairs\n\
210	             (ρ_mid undefined), so the gate (ρ_all ≥ 0.999 AND ρ_mid ≥ 0.99) was never fully exercised.\n\
211	             GREEN is withheld — supply an FT-column fixture with near-orthogonal pairs. (ρ_all = {:.5}.)",
212	            rho_all
213	        );
214	        ExitCode::FAILURE
215	    } else {
216	        let primary = rho_all.min(rho_mid);
217	        println!(
218	            "D-PALETTE-NNUE (corrected): AMBER/FENCED — min(ρ_all, ρ_mid) {:.5} below the gate. The\n\
219	             certified cosine-replacement does not clear the ρ_all≥0.999 / near-orthogonal-0.99 anchor\n\
220	             on these FT columns; the tenant holds only coarsely. A real measured result — the gate\n\
221	             returns non-zero so automation can distinguish it from GREEN.",
222	            primary
223	        );
224	        ExitCode::FAILURE
225	    }
226	}
